import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"Positioning","description":"","frontmatter":{"title":"Positioning","lang":"en-US"},"headers":[],"relativePath":"maintenance/positioning.md","filePath":"maintenance/positioning.md"}`),a={name:`maintenance/positioning.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="positioning" tabindex="-1">Positioning <a class="header-anchor" href="#positioning" aria-label="Permalink to “Positioning”">​</a></h1><h2 id="automated-positioning" tabindex="-1">Automated positioning <a class="header-anchor" href="#automated-positioning" aria-label="Permalink to “Automated positioning”">​</a></h2><p>Maintenance of the automated positioning system consists of checking the motors and making sure everything is properly tightened (use Loctite if needed; we recommend it). Troubleshooting mostly involves the motor drivers.</p><h3 id="calibrating" tabindex="-1">Calibrating <a class="header-anchor" href="#calibrating" aria-label="Permalink to “Calibrating”">​</a></h3><p>If the motors don&#39;t respond correctly, open the Zaber software, select the &#39;Basic Movements&#39; option and click the Home button. This sends the motors to their absolute zero position.</p><h3 id="restore" tabindex="-1">Restore <a class="header-anchor" href="#restore" aria-label="Permalink to “Restore”">​</a></h3><p>If sending the motors home doesn&#39;t work, the next step is to restore the affected motor. In the basic options, select the motor experiencing the issue, click on the settings icon, and choose &#39;Restore&#39;.</p><h3 id="recomendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recomendation" aria-label="Permalink to “Recommendation”">​</a></h3><p>After training is finished, send all the motors home.</p><h2 id="manual" tabindex="-1">Manual positioning <a class="header-anchor" href="#manual" aria-label="Permalink to “Manual positioning”">​</a></h2><p>The manual positioning system needs little maintenance: mainly tightening the Thorlabs parts and keeping the positioning tool in good shape.</p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};